// SPDX-License-Identifier: AGPL-3.0-only
// Prepends the SPDX header and a "generated" note to a generated file.
import { readFileSync, writeFileSync } from "node:fs";

const file = process.argv[2];
if (!file) throw new Error("usage: add-header.ts <file>");
const header =
  "// SPDX-License-Identifier: AGPL-3.0-only\n" +
  "// GENERATED by `pnpm api:client` from openapi.json. Do not edit.\n\n";
writeFileSync(file, header + readFileSync(file, "utf8"));
